// Load Cinzel at module level
const { fontFamily: cinzelFont } = loadCinzel();

// Zod Schema matching strict constraints


export type EleutherooLogoRevealProps = Record<string, any>;

// Deterministic ambient particles generator
const ambientParticles = Array.from({ length: 50 }).map((_, i) => {
  const seedX = random(`px-${i}`);
  const seedY = random(`py-${i}`);
  const seedSpeed = random(`ps-${i}`);
  const size = random(`psize-${i}`) * 4 + 2; // 2px to 6px
  return { seedX, seedY, seedSpeed, size };
});

// Deterministic eruption burst particles
const burstParticles = Array.from({ length: 60 }).map((_, i) => {
  const angle = random(`ba-${i}`) * 2 * Math.PI;
  const speed = random(`bs-${i}`) * 15 + 5;
  const size = random(`bsize-${i}`) * 4 + 2;
  const seedOpacity = random(`bo-${i}`);
  return { angle, speed, size, seedOpacity };
});

// Majestic rotating ray wedges for spiritual volumetric lighting
const Rays: React.FC<{ opacity: number; rotation: number; logoScale: number }> = ({ opacity, rotation, logoScale }) => {
  return (
    <svg
      style={{
        position: "absolute",
        left: "50%",
        top: "50%",
        width: 600 * logoScale,
        height: 600 * logoScale,
        transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
        opacity,
        pointerEvents: "none",
        mixBlendMode: "screen",
        overflow: "visible",
        transition: "none",
      }}
      viewBox="0 0 100 100"
    >
      <defs>
        <radialGradient id="ray-grad" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#FFF6D1" stopOpacity={0.5} />
          <stop offset="40%" stopColor="#DFBA6B" stopOpacity={0.15} />
          <stop offset="100%" stopColor="#DFBA6B" stopOpacity={0} />
        </radialGradient>
      </defs>
      {Array.from({ length: 12 }).map((_, i) => {
        const angle = (i * 360) / 12;
        return (
          <path
            key={i}
            d="M 50,50 L 45,0 L 55,0 Z"
            fill="url(#ray-grad)"
            transform={`rotate(${angle} 50 50)`}
            style={{ transition: "none" }}
          />
        );
      })}
    </svg>
  );
};

// Custom 4-pointed star sparkle twinkle component
const Sparkle: React.FC<{ x: number; y: number; delay: number; scale: number }> = ({ x, y, delay, scale }) => {
  const frame = useCurrentFrame();
  const t = frame - delay;
  if (t < 0) return null;

  const cycle = t % 50;
  const opacity = interpolate(cycle, [0, 15, 30, 50], [0, 1, 1, 0], { extrapolateRight: "clamp" });
  const starScale = interpolate(cycle, [0, 15, 50], [0, scale, 0], { extrapolateRight: "clamp" });

  return (
    <svg
      style={{
        position: "absolute",
        left: x,
        top: y,
        transform: `translate(-50%, -50%) scale(${starScale})`,
        opacity,
        pointerEvents: "none",
        mixBlendMode: "screen",
        width: 50,
        height: 50,
        transition: "none",
      }}
      viewBox="0 0 100 100"
    >
      <path
        d="M 50,0 Q 50,50 0,50 Q 50,50 50,100 Q 50,50 100,50 Q 50,50 50,0"
        fill="#ffffff"
      />
      <circle cx="50" cy="50" r="12" fill="#FFE082" filter="blur(2px)" />
    </svg>
  );
};

const EleutherooLogoReveal: React.FC<EleutherooLogoRevealProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 9,
  logoText = "ELEUTHERÓO",
  goldColor1 = "#F9F5E8",
  goldColor2 = "#DFBA6B",
  goldColor3 = "#8C6721",
  particleCount = 40,
  shineSpeed = 1,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Safe parsing for background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Adaptive scale to handle landscape and mobile vertical portrait viewports gracefully
  const logoScale = Math.min(width * 0.85 / 1100, height * 0.45 / 300);

  // Core coordinates
  const centerX = width / 2;
  const centerY = height / 2;

  // Assembly Timeline Configurations
  const letterAssembleEnd = 135;
  const crossAppearStart = 130;
  const crossAssembleEnd = 155;
  const burstFrame = 135;

  // Letters horizontal spacing offsets (at 1920x1080 baseline)
  const lettersConfig = [
    { char: "E", offset: -355, delay: 0 },
    { char: "L", offset: -275, delay: 8 },
    { char: "E", offset: -195, delay: 4 },
    { char: "U", offset: -115, delay: 12 },
    { char: "H", offset: 115, delay: 14 },
    { char: "E", offset: 195, delay: 6 },
    { char: "R", offset: 275, delay: 10 },
    { char: "Ó", offset: 360, delay: 2 },
    { char: "O", offset: 445, delay: 16 },
  ];

  // Camera slow continuous zoom-in
  const cameraScale = interpolate(frame, [0, 270], [0.94, 1.05], {
    easing: Easing.out(Easing.quad),
    extrapolateRight: "clamp",
  });

  // Background clean luxury vignette
  const bgGradient = transparentBackground
    ? "transparent"
    : "radial-gradient(circle, #ffffff 50%, #f6f6f6 100%)";

  return (
    <AbsoluteFill style={{ background: bgGradient, backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Cinematic Camera Frame Container */}
      <div
        style={{
          width: "100%",
          height: "100%",
          transform: `scale(${cameraScale})`,
          position: "relative",
          transition: "none",
        }}
      >
        {/* Divine Light Rays rotating behind the cross */}
        {(() => {
          const rayOpacity = interpolate(frame, [crossAppearStart, 150, 270], [0, 0.8, 0.25], {
            extrapolateRight: "clamp",
          });
          const rayRotation = frame * 0.15;
          return <Rays opacity={rayOpacity} rotation={rayRotation} logoScale={logoScale} />;
        })()}

        {/* Ambient Drifting Dust Particles */}
        {ambientParticles.slice(0, particleCount).map((p, i) => {
          const yPos = ((p.seedY * height - frame * (0.4 + p.seedSpeed * 1.1)) % height + height) % height;
          const xPos = p.seedX * width + Math.sin(frame * 0.025 + p.seedX * 100) * 40;
          const opacity = 0.25 + Math.sin(frame * 0.04 + p.seedX * 60) * 0.35;

          return (
            <div
              key={`ambient-${i}`}
              style={{
                position: "absolute",
                left: xPos,
                top: yPos,
                width: p.size * logoScale,
                height: p.size * logoScale,
                borderRadius: "50%",
                background: `radial-gradient(circle, #ffe596 0%, rgba(223,186,107,0.3) 70%, transparent 100%)`,
                opacity: opacity,
                boxShadow: "0 0 8px rgba(255, 215, 0, 0.4)",
                pointerEvents: "none",
                transition: "none",
              }}
            />
          );
        })}

        {/* Burst Eruption Particles from center */}
        {burstParticles.map((bp, i) => {
          const f = frame - burstFrame;
          if (f < 0) return null;

          const dist = interpolate(f, [0, 65], [0, bp.speed * 28 * logoScale], {
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.quad),
          });
          const xPos = centerX + Math.cos(bp.angle) * dist;
          const yPos = centerY + Math.sin(bp.angle) * dist;
          const opacity = interpolate(f, [0, 8, 45], [0, 1, 0], {
            extrapolateRight: "clamp",
          });

          return (
            <div
              key={`burst-${i}`}
              style={{
                position: "absolute",
                left: xPos,
                top: yPos,
                width: bp.size * logoScale,
                height: bp.size * logoScale,
                borderRadius: "50%",
                background: "#FFE082",
                boxShadow: "0 0 10px #DFBA6B, 0 0 20px rgba(255,255,255,0.8)",
                opacity: opacity,
                pointerEvents: "none",
                transition: "none",
              }}
            />
          );
        })}

        {/* Volumetric Center Glow Flare at eruption */}
        {(() => {
          const flareProgress = frame - burstFrame;
          if (flareProgress < 0) return null;

          const scale = interpolate(flareProgress, [0, 15, 60], [0, 3.5, 0], {
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.quad),
          });
          const opacity = interpolate(flareProgress, [0, 8, 50], [0, 0.95, 0], {
            extrapolateRight: "clamp",
          });

          return (
            <div
              style={{
                position: "absolute",
                left: centerX,
                top: centerY,
                width: 300 * logoScale,
                height: 300 * logoScale,
                transform: `translate(-50%, -50%) scale(${scale})`,
                background: "radial-gradient(circle, rgba(255,255,255,1) 0%, rgba(255,230,150,0.8) 30%, rgba(223,186,107,0.1) 70%, transparent 100%)",
                borderRadius: "50%",
                opacity,
                pointerEvents: "none",
                mixBlendMode: "screen",
                transition: "none",
              }}
            />
          );
        })()}

        {/* Divine Light Beam (vertical forging beam) */}
        {(() => {
          const beamProgress = frame - burstFrame;
          if (beamProgress < 0) return null;

          const widthScale = interpolate(beamProgress, [0, 8, 40], [0.1, 1.5, 0], {
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.quad),
          });
          const opacity = interpolate(beamProgress, [0, 6, 35], [0, 1, 0], {
            extrapolateRight: "clamp",
          });

          return (
            <div
              style={{
                position: "absolute",
                left: centerX,
                top: 0,
                width: 140 * logoScale * widthScale,
                height: height,
                transform: "translateX(-50%)",
                background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.95) 30%, rgba(255,240,180,1) 50%, rgba(255,255,255,0.95) 70%, transparent 100%)",
                opacity,
                filter: "blur(4px)",
                pointerEvents: "none",
                mixBlendMode: "screen",
                transition: "none",
              }}
            />
          );
        })()}

        {/* Ornate Gold Cross in the center acting as T */}
        {(() => {
          const crossProgress = interpolate(frame, [crossAppearStart, crossAssembleEnd], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.bezier(0.16, 1, 0.3, 1),
          });

          const crossScale = interpolate(crossProgress, [0, 0.75, 1], [0.2, 1.15, 1], {
            extrapolateRight: "clamp",
          });

          // Logo slow luxury pulse once assembled
          const pulse = frame >= letterAssembleEnd ? Math.sin((frame - letterAssembleEnd) * 0.04) * 0.012 : 0;
          const finalScale = (1 + pulse) * logoScale;

          // Sweeping sheen progress
          const sheenProgress = interpolate(frame, [170, 230], [-150, 250], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          return (
            <div
              style={{
                position: "absolute",
                left: centerX,
                top: centerY,
                width: 140 * logoScale,
                height: 196 * logoScale,
                transform: `translate(-50%, -36.5%) scale(${crossScale * finalScale / logoScale})`,
                opacity: crossProgress,
                pointerEvents: "none",
                filter: "drop-shadow(0px 8px 20px rgba(140, 103, 33, 0.35))",
                transition: "none",
              }}
            >
              <svg
                width="100%"
                height="100%"
                viewBox="0 0 100 140"
                style={{ overflow: "visible", transition: "none" }}
              >
                <defs>
                  {/* Premium gold gradient */}
                  <linearGradient id="gold-grad" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" stopColor={goldColor1} />
                    <stop offset="30%" stopColor={goldColor2} />
                    <stop offset="60%" stopColor="#8C6721" />
                    <stop offset="85%" stopColor={goldColor2} />
                    <stop offset="100%" stopColor="#5c4314" />
                  </linearGradient>

                  {/* Reflection shine gradient */}
                  <linearGradient id="sheen-grad" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset={`${sheenProgress - 30}%`} stopColor="transparent" />
                    <stop offset={`${sheenProgress}%`} stopColor="rgba(255, 255, 255, 0.85)" />
                    <stop offset={`${sheenProgress + 15}%`} stopColor="rgba(255, 255, 255, 1)" />
                    <stop offset={`${sheenProgress + 30}%`} stopColor="rgba(255, 255, 255, 0.85)" />
                    <stop offset={`${sheenProgress + 60}%`} stopColor="transparent" />
                  </linearGradient>

                  {/* Dark bevel outline gradient */}
                  <linearGradient id="dark-bevel-grad" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" stopColor="#DFBA6B" />
                    <stop offset="50%" stopColor="#8C6721" />
                    <stop offset="100%" stopColor="#301f02" />
                  </linearGradient>
                </defs>

                {/* Base Ornate Cross Shadow / Dark Bevel Outer */}
                <path
                  d="M 50,10 Q 47,22 41,24 Q 44,28 43,38 L 37,38 Q 27,37 25,31 Q 23,38 13,40 Q 23,42 25,49 Q 27,43 37,42 L 43,42 L 43,80 Q 40,105 37,110 Q 44,115 50,135 Q 56,115 63,110 Q 60,105 57,80 L 57,42 L 63,42 Q 73,43 75,49 Q 77,42 87,40 Q 77,38 75,31 Q 73,37 63,38 L 57,38 Q 56,28 59,24 Q 53,22 50,10 Z"
                  fill="url(#dark-bevel-grad)"
                  transform="translate(1, 1)"
                  style={{ transition: "none" }}
                />

                {/* Main Ornate Cross Gold Body */}
                <path
                  d="M 50,10 Q 47,22 41,24 Q 44,28 43,38 L 37,38 Q 27,37 25,31 Q 23,38 13,40 Q 23,42 25,49 Q 27,43 37,42 L 43,42 L 43,80 Q 40,105 37,110 Q 44,115 50,135 Q 56,115 63,110 Q 60,105 57,80 L 57,42 L 63,42 Q 73,43 75,49 Q 77,42 87,40 Q 77,38 75,31 Q 73,37 63,38 L 57,38 Q 56,28 59,24 Q 53,22 50,10 Z"
                  fill="url(#gold-grad)"
                  style={{ transition: "none" }}
                />

                {/* Reflection Sweep overlay on Cross */}
                {frame >= 170 && (
                  <path
                    d="M 50,10 Q 47,22 41,24 Q 44,28 43,38 L 37,38 Q 27,37 25,31 Q 23,38 13,40 Q 23,42 25,49 Q 27,43 37,42 L 43,42 L 43,80 Q 40,105 37,110 Q 44,115 50,135 Q 56,115 63,110 Q 60,105 57,80 L 57,42 L 63,42 Q 73,43 75,49 Q 77,42 87,40 Q 77,38 75,31 Q 73,37 63,38 L 57,38 Q 56,28 59,24 Q 53,22 50,10 Z"
                    fill="url(#sheen-grad)"
                    style={{ transition: "none", mixBlendMode: "overlay" }}
                  />
                )}

                {/* Central Bevel Ridge Highlight Line */}
                <path
                  d="M 50,10 L 50,135 M 13,40 L 87,40"
                  stroke="rgba(255, 255, 255, 0.45)"
                  strokeWidth="1.2"
                  fill="none"
                  strokeLinecap="round"
                  style={{ transition: "none" }}
                />
              </svg>
            </div>
          );
        })()}

        {/* Elegant Flying Spiral Letters */}
        {lettersConfig.map((item) => {
          // Progress of letter transition
          const progress = interpolate(frame, [item.delay, letterAssembleEnd], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.bezier(0.16, 1, 0.3, 1),
          });

          // Spiral trajectory calculations
          const spiralTurns = 1.8;
          const baseAngle = (item.offset > 0 ? 1 : -1) * Math.PI * 0.45;
          const angle = (1 - progress) * spiralTurns * 2 * Math.PI + baseAngle;
          const radius = (1 - progress) * (480 + Math.abs(item.offset) * 0.45);

          // Position lock coordinates
          const targetX = item.offset * logoScale;
          const currentX = targetX + Math.cos(angle) * radius * logoScale;
          const currentY = Math.sin(angle) * radius * 0.35 * logoScale;

          // 3D Rotations
          const rotateX = (1 - progress) * 360 * 1.5;
          const rotateY = (1 - progress) * 360 * 1.2;
          const rotateZ = (1 - progress) * 120;

          const letterOpacity = interpolate(progress, [0, 0.12], [0, 1], {
            extrapolateRight: "clamp",
          });

          const letterScale = interpolate(progress, [0, 0.15, 1], [0.3, 1.15, 1], {
            extrapolateRight: "clamp",
          });

          // Logo slow luxury pulse once assembled
          const pulse = frame >= letterAssembleEnd ? Math.sin((frame - letterAssembleEnd) * 0.04) * 0.012 : 0;
          const finalScale = (1 + pulse) * letterScale;

          // Sweep sheen position
          const sheenProgress = interpolate(frame, [170, 230], [-150, 250], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          // Style structure
          const textContainerStyle: React.CSSProperties = {
            position: "absolute",
            left: centerX + currentX,
            top: centerY + currentY,
            transform: `translate(-50%, -50%) rotateX(${rotateX}deg) rotateY(${rotateY}deg) rotateZ(${rotateZ}deg) scale(${finalScale})`,
            transformStyle: "preserve-3d",
            opacity: letterOpacity,
            fontSize: `${105 * logoScale}px`,
            fontWeight: "bold",
            fontFamily: cinzelFont,
            color: "transparent",
            backgroundImage: `linear-gradient(135deg, ${goldColor1} 0%, ${goldColor2} 30%, ${goldColor3} 65%, ${goldColor2} 85%, #5c4314 100%)`,
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
            filter: "drop-shadow(0px 6px 12px rgba(140, 103, 33, 0.3))",
            userSelect: "none",
            pointerEvents: "none",
            transition: "none",
          };

          const shineStyle: React.CSSProperties = {
            position: "absolute",
            left: 0,
            top: 0,
            width: "100%",
            height: "100%",
            color: "transparent",
            backgroundImage: `linear-gradient(120deg, transparent 35%, rgba(255, 255, 255, 0.85) 45%, rgba(255, 255, 255, 1) 50%, rgba(255, 255, 255, 0.85) 55%, transparent 65%)`,
            backgroundSize: "200% 100%",
            backgroundPosition: `${sheenProgress}% 0%`,
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
            opacity: frame >= 170 ? 1 : 0,
            mixBlendMode: "overlay",
            pointerEvents: "none",
            transition: "none",
          };

          // Render ghost trail elements during spiral journey
          const renderTrails = progress < 0.98;

          return (
            <React.Fragment key={item.char}>
              {/* Dynamic Trail Render */}
              {renderTrails &&
                Array.from({ length: 5 }).map((_, j) => {
                  const trailDelay = j * 1.5;
                  const trailFrame = Math.max(0, frame - trailDelay);
                  const trailProgress = interpolate(trailFrame, [item.delay, letterAssembleEnd], [0, 1], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                    easing: Easing.bezier(0.16, 1, 0.3, 1),
                  });

                  if (trailProgress <= 0 || trailProgress >= 0.98) return null;

                  const tAngle = (1 - trailProgress) * spiralTurns * 2 * Math.PI + baseAngle;
                  const tRadius = (1 - trailProgress) * (480 + Math.abs(item.offset) * 0.45);
                  const tx = targetX + Math.cos(tAngle) * tRadius * logoScale;
                  const ty = Math.sin(tAngle) * tRadius * 0.35 * logoScale;

                  const tRotateX = (1 - trailProgress) * 360 * 1.5;
                  const tRotateY = (1 - trailProgress) * 360 * 1.2;
                  const tRotateZ = (1 - trailProgress) * 120;
                  const trailOpacity = interpolate(trailProgress, [0, 0.15], [0, 1]) * (1 - j / 6) * 0.28;

                  return (
                    <div
                      key={`trail-${item.char}-${j}`}
                      style={{
                        position: "absolute",
                        left: centerX + tx,
                        top: centerY + ty,
                        transform: `translate(-50%, -50%) rotateX(${tRotateX}deg) rotateY(${tRotateY}deg) rotateZ(${tRotateZ}deg) scale(${letterScale * (1 - j * 0.05)})`,
                        opacity: trailOpacity,
                        fontSize: `${105 * logoScale}px`,
                        fontWeight: "bold",
                        fontFamily: cinzelFont,
                        color: "transparent",
                        backgroundImage: "linear-gradient(135deg, rgba(255,235,150,0.8) 0%, rgba(223,186,107,0.5) 100%)",
                        WebkitBackgroundClip: "text",
                        WebkitTextFillColor: "transparent",
                        filter: "blur(2px) drop-shadow(0 0 8px rgba(255,215,0,0.5))",
                        pointerEvents: "none",
                        transition: "none",
                      }}
                    >
                      {item.char}
                    </div>
                  );
                })}

              {/* Main Elegant Letter */}
              <div style={textContainerStyle}>
                {item.char}
                {/* Metallic shine sweep layer */}
                <div style={shineStyle}>{item.char}</div>
              </div>
            </React.Fragment>
          );
        })}

        {/* Premium Tiny Corner Twinkles traveling on letter edges */}
        <Sparkle x={centerX} y={centerY - 92 * logoScale} delay={145} scale={0.7} />
        <Sparkle x={centerX - 355 * logoScale} y={centerY} delay={165} scale={0.6} />
        <Sparkle x={centerX + 360 * logoScale} y={centerY - 10 * logoScale} delay={180} scale={0.65} />
      </div>
    </AbsoluteFill>
  );
};

export default EleutherooLogoReveal;